INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (1, 'environment', 'Environment', 'Environmental, timing and orchard context', 1);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (2, 'soil', 'Soil & root-zone', 'Soil and root-zone', 2);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (3, 'tree-identity', 'Tree identity & establishment', 'Tree identity, establishment and natural developmental traits', 3);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (4, 'roots', 'Root system', 'Root system', 4);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (5, 'canopy', 'Canopy & yield', 'Tree size, canopy, crop load and productivity', 5);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (6, 'buds', 'Buds & dormancy', 'Bud, dormancy and reserve status', 6);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (7, 'leaves', 'Leaves', 'Leaf morphology, physiology and nutrients', 7);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (8, 'flowering', 'Flowering & pollination', 'Flowering, pollination and flower-bud formation', 8);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (9, 'fruit', 'Fruit growth & quality', 'Fruit growth, maturity and quality', 9);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (10, 'health', 'IPDM & senescence', 'IPDM, senescence and end of productive life', 10);
INSERT INTO measurement_category (category_id, category_key, short_label, full_name, display_order) VALUES (11, 'other', 'Other', 'Not covered by a Table S4B protocol', 11);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (1, 'Air temperature, relative humidity, wind speed/direction, rainfall and short-wave radiation', 'Environmental, timing and orchard context', 1, NULL, 'NDG00; ODG00-03; OAR00-93', 'Air temperature, relative humidity, wind, rainfall and short-wave radiation are recorded with a calibrated orchard weather station following WMO siting and exposure guidance.', 'Paper + authoritative protocol', NULL, 'orchard weather station');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (2, 'Photosynthetically active radiation (PAR/PPFD)', 'Environmental, timing and orchard context', 1, NULL, 'ODG02; OAR10-82', 'PAR/PPFD is measured with a quantum sensor or linear ceptometer positioned above and below the canopy.', 'Source paper protocol', NULL, 'quantum sensor; linear ceptometer; ceptometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (3, 'Soil temperature', 'Environmental, timing and orchard context', 1, NULL, 'NDG00; ODG00-03; OAR00-93', 'Soil temperature is recorded with temperature probes installed at fixed root-zone depths.', 'Paper + authoritative protocol', NULL, 'temperature probe');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (4, 'Phenological event date, DOY, DAFB and photoperiod', 'Environmental, timing and orchard context', 1, NULL, 'OAR00-93', 'Phenology is scored from repeated BBCH observations; DOY and DAFB are calculated from the observation date and full-bloom date.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (5, 'Composite soil sample', 'Soil and root-zone', 2, NULL, 'NDG00; ODG00-03', 'A composite soil sample is prepared by mixing 15-20 subsamples collected from a uniform orchard block at feeder-root depth.', 'Authoritative protocol / standard', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (6, 'Soil pH and available nutrient profile (SOC, total/extractable N, Olsen P, exchangeable K and named nutrients)', 'Soil and root-zone', 2, NULL, 'NDG00; ODG00-03', 'Soil pH and extractable nutrients are measured from the composite sample using the laboratory extraction specified for each analyte.', 'Paper + authoritative protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (7, 'Volumetric soil water content (VWC)', 'Soil and root-zone', 2, NULL, 'NDG00; ODG00-03; OAR10-93', 'Volumetric soil water content is measured with calibrated capacitance or TDR probes installed at representative root-zone depths.', 'Paper + authoritative protocol', NULL, 'capacitance; TDR probe');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (8, 'Soil-water potential / tension', 'Soil and root-zone', 2, NULL, 'ODG01-03; OAR10-82', 'Soil-water potential is measured with tensiometers or matric-potential sensors installed in good soil contact at root-zone depth.', 'Authoritative protocol / standard', NULL, 'tensiometer; matric-potential sensor');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (9, 'Apparent soil electrical conductivity (ECa)', 'Soil and root-zone', 2, NULL, 'ODG00-03; OAR10-82', 'Apparent soil electrical conductivity is mapped with a georeferenced electromagnetic or conductivity sensor survey.', 'Source paper protocol', NULL, 'electromagnetic or conductivity sensor');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (10, 'Soil texture, bulk density, porosity, saturated hydraulic conductivity and penetration resistance', 'Soil and root-zone', 2, NULL, 'ODG00-03', 'Soil texture, bulk density, porosity, hydraulic conductivity and penetration resistance are measured with standard NRCS field and laboratory procedures.', 'Paper + authoritative protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (11, 'Scion/rootstock identity and tree age', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'ODG00-03', 'Scion, rootstock and planting date are recorded as tree-level metadata; tree age is calculated from the planting date.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (12, 'Graft-union height, row spacing, within-row spacing, planting density and row orientation', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'ODG00-03', 'Graft-union height and tree/row spacing are measured with a tape or survey pole; planting density is calculated from spacing and row orientation from field bearing.', 'Source paper protocol', NULL, 'survey pole; tape');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (13, 'Main-stem node number and flowering-node position', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'NDG01-03', 'Main-stem nodes are counted sequentially from a fixed basal node; the node carrying the first flower is recorded with the same numbering convention.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (14, 'Leaf blade area, length, width, aspect ratio, outline/shape and serration', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'NDG01-03', 'Leaf area, length and width are obtained from flattened leaves scanned or photographed with a scale; shape and serration are scored with UPOV descriptors.', 'Paper + authoritative protocol', NULL, 'scanned');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (15, 'Leaf attitude/side-shoot angle, thorn presence/density and adventitious-root presence', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'NDG01-03', 'Leaf attitude, side-shoot angle, thorniness and adventitious rooting are scored on fixed plant positions using UPOV apple descriptors.', 'Authoritative protocol / standard', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (16, 'Leaf epidermal cell area/number, stomatal density, trichome density and leaf thickness', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'NDG01-03; OAR10-82', 'Epidermal cell size, stomatal/trichome density and leaf thickness are measured from calibrated microscopic images of fully expanded leaves.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (17, 'Leaf mass per area (LMA) / specific leaf weight', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'NDG01-03; OAR10-82', 'LMA is calculated from one-sided leaf area and oven-dry mass of the same leaves.', 'Source paper protocol', NULL, 'oven-dry');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (18, 'Phase-related phenolic markers (phloridzin, myricitrin, caffeic acid)', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'NDG01-03', 'Phloridzin, myricitrin and caffeic acid are quantified from defined tissues by HPLC using analytical standards.', 'Source paper protocol', NULL, 'HPLC');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (19, 'Shoot length, elongation rate and terminal growth cessation', 'Tree identity, establishment and natural developmental traits', 3, NULL, 'NDG01-04; OAR30-39; OAR79', 'Shoot length is measured repeatedly from shoot base to tip with a ruler or tape; elongation rate is calculated between dates.', 'Source paper protocol', NULL, 'tape');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (20, 'Root length, surface area, mean/maximum diameter and volume', 'Root system', 4, NULL, 'NDG01; ODG03', 'Washed roots are scanned against a contrasting background and root length, area, diameter and volume are obtained by root-image analysis.', 'Source paper protocol', NULL, 'root-image analysis; scanned');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (21, 'Primary-root count; fine/medium/coarse root length; root dry mass; root-system width/depth/projected area', 'Root system', 4, NULL, 'ODG03', 'Excavated roots are counted, separated into diameter classes, scanned for dimensions and oven-dried for dry mass.', 'Source paper protocol', NULL, 'scanned');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (22, 'Rootstock:scion diameter ratio at graft union', 'Root system', 4, NULL, 'ODG03', 'Rootstock and scion diameters are measured with calipers immediately below and above the graft union and expressed as a diameter ratio.', 'Source paper protocol', NULL, 'calipers');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (23, 'Effective rooting depth and root water potential', 'Root system', 4, NULL, 'ODG01-03; OAR50-82', 'Effective rooting depth is obtained from depth-resolved root observations; root water potential is measured on sampled roots with the cited pressure-potential method.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (24, 'Fine- and coarse-root starch', 'Root system', 4, NULL, 'OAR01-04', 'Fine and coarse roots are separated by diameter class, dried and ground, and starch is measured after extraction and hydrolysis.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (25, 'Trunk circumference and trunk cross-sectional area (TCSA)', 'Tree size, canopy, crop load and productivity', 5, NULL, 'NDG01-04; ODG01-03', 'TCSA is derived from trunk circumference measured with a tape around a smooth trunk surface 30 cm above the graft union: TCSA=C^2/(4π).', 'Source paper protocol', 'TCSA = C^{2}/(4\pi)', 'tape');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (26, 'Tree height, canopy width, projected area and canopy volume', 'Tree size, canopy, crop load and productivity', 5, NULL, 'ODG01-02; OAR10-82', 'Tree height and orthogonal canopy widths are measured with a tape or survey pole; projected area and canopy volume are calculated from these dimensions.', 'Source paper protocol', NULL, 'survey pole; tape');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (27, 'Leaf area index (LAI): direct/reconstructed', 'Tree size, canopy, crop load and productivity', 5, 'direct/reconstructed', 'ODG02; OAR10-82', 'Direct LAI is total leaf area per tree divided by ground area; leaf area is measured with a leaf-area meter and scaled from sampled leaves/shoots.', 'Source paper protocol', NULL, 'leaf-area meter');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (28, 'Leaf area index (LAI): hemispherical imaging', 'Tree size, canopy, crop load and productivity', 5, 'hemispherical imaging', 'ODG02; OAR10-82', 'LAI is estimated from hemispherical canopy images acquired with a CI-110 Plant Canopy Imager and analysed with the CI-110 canopy-analysis software.', 'Source paper protocol', NULL, 'CI-110 Plant Canopy Imager');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (29, 'Leaf area index (LAI): optical canopy analyser', 'Tree size, canopy, crop load and productivity', 5, 'optical canopy analyser', 'ODG02; OAR10-82', 'Optical LAI is measured with an LAI-2200C using matched above- and below-canopy readings following the manufacturer''s isolated-row protocol.', 'Authoritative protocol / standard', NULL, 'LAI-2200C');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (30, 'Canopy light interception', 'Tree size, canopy, crop load and productivity', 5, NULL, 'ODG02; OAR10-82', 'Canopy light interception is calculated from above- and below-canopy PAR measured with a linear ceptometer: 1-I_below/I_above.', 'Source paper protocol', '1 - I_{below}/I_{above}', 'linear ceptometer; ceptometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (31, 'Crop load / fruit number per tree or TCSA; blossom-cluster density', 'Tree size, canopy, crop load and productivity', 5, NULL, 'ODG02-03; OAR40-82', 'Crop load is obtained by counting fruit or blossom clusters per tree and, when required, dividing the count by same-tree TCSA.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (32, 'Annual yield, cumulative yield and yield efficiency', 'Tree size, canopy, crop load and productivity', 5, NULL, 'ODG02-03; OAR82', 'Yield is the total fruit mass harvested per tree; yield efficiency is yield divided by same-tree TCSA.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (33, 'Flowering intensity and return bloom', 'Tree size, canopy, crop load and productivity', 5, NULL, 'ODG02-03; OAR40-59', 'Flowering intensity is obtained from blossom-cluster counts or a fixed bloom scale; return bloom is measured on the same trees the following season.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (34, 'Annual trunk radial increment', 'Tree size, canopy, crop load and productivity', 5, NULL, 'ODG03', 'Annual trunk radial increment is measured from cross-dated increment cores collected at a fixed trunk position.', 'Source paper protocol', NULL, 'increment core');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (35, 'Bud count and external bud size', 'Bud, dormancy and reserve status', 6, NULL, 'OAR00-04; ODG01-02', 'Buds are counted on a fixed shoot/tree basis and bud dimensions are measured with calipers or scale-referenced images.', 'Paper + authoritative protocol', NULL, 'calipers');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (36, 'Bud fresh mass, dry mass and water content', 'Bud, dormancy and reserve status', 6, NULL, 'OAR00-04', 'Bud water content is derived from fresh mass and oven-dry mass measured on the same bud sample.', 'Source paper protocol', NULL, 'oven-dry');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (37, 'Chilling accumulation (CH, CU, CP) and chilling requirement', 'Bud, dormancy and reserve status', 6, NULL, 'OAR00-04', 'Chilling is calculated from temperature records with the named model (CH, Utah CU or Dynamic Model CP); chilling requirement uses a stated budbreak endpoint.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (38, 'Budbreak percentage under forcing', 'Bud, dormancy and reserve status', 6, NULL, 'OAR00-04', 'Budbreak percentage is measured by forcing dormant shoots under controlled conditions and scoring buds at fixed intervals with a stated BBCH criterion.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (39, 'Bud starch, soluble sugars, sucrose/glucose/fructose, sorbitol and total carbohydrate reserves', 'Bud, dormancy and reserve status', 6, NULL, 'OAR00-04', 'Bud soluble sugars are extracted and quantified chromatographically or enzymatically; starch is measured from the residual tissue after hydrolysis.', 'Paper + authoritative protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (40, 'Leaf type, fresh/dry mass, area, number, water content, volume and internal gas-space volume', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR10-82', 'Leaf fresh mass, area and number are measured on a fixed leaf class; dry mass follows oven drying and water content is derived from fresh and dry mass.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (41, 'SPAD chlorophyll index', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR10-82', 'SPAD is measured on recently mature leaves with a SPAD meter using two readings on opposite sides of the midrib.', 'Source paper protocol', NULL, 'SPAD meter');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (42, 'Leaf chlorophyll a, chlorophyll b, total chlorophyll, a:b ratio and carotenoids', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR10-93', 'Leaf chlorophylls and carotenoids are extracted from a fixed leaf mass/area and quantified spectrophotometrically or chromatographically.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (43, 'Leaf mineral nutrients (N, P, K, Ca, Mg and micronutrients)', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR10-93', 'Apple leaf nutrients are measured from recently mature leaves collected using the WSU leaf-tissue sampling protocol and analysed by element-specific laboratory methods.', 'Paper + authoritative protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (44, 'Net photosynthesis, stomatal conductance, transpiration and related gas-exchange metrics', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR10-93', 'Net photosynthesis, stomatal conductance and transpiration are measured on defined leaves with an infrared gas analyser under fixed chamber conditions.', 'Source paper protocol', NULL, 'infrared gas analyser');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (45, 'Leaf dark respiration', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR90-93', 'Leaf dark respiration is measured as CO_2 exchange with an infrared gas analyser after dark acclimation.', 'Source paper protocol', NULL, 'infrared gas analyser');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (46, 'Chlorophyll fluorescence (F_v/F_m)', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR80-93', 'F_v/F_m is measured on dark-adapted leaves with a PAM fluorometer from minimum and maximum fluorescence.', 'Source paper protocol', NULL, 'PAM fluorometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (47, 'Stem water potential by pressure chamber', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR10-82', 'Midday stem water potential is measured with a pressure chamber on a shaded lower-canopy leaf bagged for at least 10 min and measured immediately after excision.', 'Authoritative protocol / standard', NULL, 'pressure chamber');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (48, 'Trunk water potential by embedded microtensiometer', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR30-82', 'Trunk water potential is recorded continuously with an embedded microtensiometer installed on a flat trunk surface.', 'Source paper protocol', NULL, 'tensiometer; microtensiometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (49, 'Canopy temperature and T_c-T_a', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR10-82', 'Canopy temperature is measured with an infrared radiometer or thermal camera and T_c-T_a is calculated from simultaneous air temperature.', 'Source paper protocol', NULL, 'infrared radiometer; thermal camera');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (50, 'Continuous trunk diameter and maximum daily trunk shrinkage (MDS)', 'Leaf morphology, physiology and nutrients', 7, NULL, 'OAR30-82', 'Continuous trunk diameter is measured with a linear displacement dendrometer; MDS is the daily maximum minus daily minimum diameter.', 'Source paper protocol', 'MDS = D_{max,daily} - D_{min,daily}', 'dendrometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (51, 'Flower-cluster count, flowers per cluster, bloom percentage, flowering date and fruit set', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR40-70', 'Flower clusters and open flowers are counted on fixed trees/branches; bloom percentage and fruit set are calculated from the same tagged population.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (52, 'Flower / fruitlet cell count and floral microscopy', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR40-70', 'Flower or fruitlet cells are counted from fixed, sectioned tissues imaged microscopically along a defined anatomical plane.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (53, 'Pollinator visitation rate and flower-standardized visitation', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR50-59', 'Pollinator visitation is measured as flower visits recorded during fixed timed observations on a known number of open flowers.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (54, 'Pollen load on flower visitors', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR50-59', 'Pollen load is measured by removing pollen from captured flower visitors and counting grains microscopically.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (55, 'Pollen-tube progression and controlled pollination', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR50-59', 'Pollen-tube progression is measured in controlled-pollinated flowers stained with aniline blue and examined by fluorescence microscopy.', 'Source paper protocol', NULL, 'fluorescence microscopy; aniline blue');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (56, 'Pollen viability and in-vitro germination', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR40-59', 'Pollen viability is scored by FDA fluorescence and in-vitro germination by the cited sucrose/mineral germination medium.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (57, 'Flowering overlap, pollination-to-fertilization interval, stigmatic receptivity and effective pollination period (EPP)', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR50-59', 'Flowering overlap is calculated from cultivar bloom windows; receptivity, fertilization interval and EPP are obtained from timed controlled-pollination observations.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (58, 'Flower-bud histological stage, meristem diameter/height, appendage number and plastochron', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR60-62', 'Flower-bud stage and meristem dimensions are measured from FAA-fixed, paraffin-embedded serial sections examined by light microscopy.', 'Source paper protocol', NULL, 'light microscopy');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (59, 'Bourse-bud phytohormones and defined metabolic analytes', 'Flowering, pollination and flower-bud formation', 8, NULL, 'OAR60-62', 'Bourse-bud hormones are extracted from frozen tissue and quantified by targeted UHPLC-MS/MS using internal standards.', 'Source paper protocol', NULL, 'UHPLC-MS/MS; LC-MS/MS; HPLC');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (60, 'Fruit diameter, fresh mass, growth rate and fruitlet retention/abscission', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'Fruit diameter is measured at the equator with digital calipers and fresh mass with a balance; repeated tagged-fruit measurements give growth and retention.', 'Source paper protocol', NULL, 'calipers; balance');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (61, 'Fruit cortex cell-layer number, cell diameter, projected cell area, CSSI and CNI', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-79', 'Fruit cortex cells are measured from calibrated histological images; layer number and cell dimensions are used to calculate CSSI and CNI.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (62, 'Fruit biochemical starch concentration', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'Fruit starch concentration is measured enzymatically from cortex tissue after removal of soluble sugars.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (63, 'Fruit firmness', 'Fruit growth, maturity and quality', 9, NULL, 'OAR80-82', 'Fruit firmness is measured on peeled equatorial sides with an 11.1-mm penetrometer probe following the University of Maryland apple maturity protocol.', 'Paper + authoritative protocol', NULL, 'penetrometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (64, 'Soluble solids concentration (SSC)', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'SSC is measured from expressed apple juice with a calibrated refractometer and reported as ^.', 'Paper + authoritative protocol', NULL, 'refractometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (65, 'Titratable acidity and fruit juice pH', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'Titratable acidity is measured by NaOH titration of a known juice volume; juice pH is measured with a calibrated pH meter.', 'Paper + authoritative protocol', NULL, 'pH meter');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (66, 'Starch-iodine pattern index and Streif index', 'Fruit growth, maturity and quality', 9, NULL, 'OAR80-82', 'The starch index is measured on an equatorial fruit half stained with iodine-KI and scored against the cultivar chart following the WSU apple harvest protocol.', 'Paper + authoritative protocol', NULL, 'iodine');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (67, 'Fruit dry mass, dry matter and density', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'Fruit dry matter is calculated from fresh and oven-dry mass; density is fruit mass divided by displaced or geometrically measured volume.', 'Source paper protocol', NULL, 'oven-dry');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (68, 'Background skin colour (L^*,a^*,b^*, hue, chroma)', 'Fruit growth, maturity and quality', 9, NULL, 'OAR80-82', 'Background skin colour is measured at fixed fruit positions with a calibrated colorimeter or spectrophotometer in L^*a^*b^* space.', 'Source paper protocol', NULL, 'colorimeter; spectrophotometer');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (69, 'Fruit peel chlorophyll, carotenoids and anthocyanins', 'Fruit growth, maturity and quality', 9, NULL, 'OAR80-82', 'Peel chlorophylls, carotenoids and anthocyanins are extracted from a fixed peel area/mass and quantified spectrophotometrically or by HPLC.', 'Source paper protocol', NULL, 'HPLC');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (70, 'Internal ethylene concentration and ethylene production rate', 'Fruit growth, maturity and quality', 9, NULL, 'OAR80-82', 'Internal ethylene is measured from core-cavity gas by GC-FID; production rate is measured from headspace accumulation of a fruit sealed for a known time.', 'Source paper protocol', NULL, 'GC-FID');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (71, 'Index of absorbance difference (I_AD)', 'Fruit growth, maturity and quality', 9, NULL, 'OAR80-82', 'I_AD is measured with a DA meter at fixed equatorial positions as A_670-A_720.', 'Paper + authoritative protocol', 'I_{AD} = A_{670} - A_{720}', 'DA meter');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (72, 'Fruit surface and near-surface tissue temperature', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'Fruit surface temperature is obtained from calibrated thermal images; near-surface tissue temperature is measured with a probe at a fixed insertion depth.', 'Source paper protocol', NULL, 'thermal image');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (73, 'Fruit mineral nutrients (N, P, K, Ca, Mg, B, Cu, Fe, Mn, Zn)', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'Fruit mineral nutrients are measured from dried, ground fruit tissue after element-specific digestion using Kjeldahl, AAS or ICP methods.', 'Source paper protocol', NULL, 'AAS; ICP; Kjeldahl');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (74, 'Fruit soluble sugars and sorbitol', 'Fruit growth, maturity and quality', 9, NULL, 'OAR70-82', 'Fruit glucose, fructose, sucrose and sorbitol are extracted from defined tissue and quantified by HPLC or enzymatic analysis.', 'Source paper protocol', NULL, 'HPLC');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (75, 'Postharvest fruit mass loss / water-loss rate', 'Fruit growth, maturity and quality', 9, NULL, 'OAR82; postharvest', 'Postharvest water loss is measured by repeatedly weighing the same fruit during storage and expressing mass loss relative to initial mass.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (76, 'Disease incidence and disease severity', 'IPDM, senescence and end of productive life', 10, NULL, 'ODG01-03; OAR10-93', 'Disease incidence is affected units divided by units assessed; severity is scored with the named disease scale following the UC IPM apple protocol.', 'Paper + authoritative protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (77, 'Mite eggs/motile mites, aphid colonies, codling-moth trap capture and pest-damaged fruit/russet', 'IPDM, senescence and end of productive life', 10, NULL, 'ODG01-03; OAR10-82', 'Mites, aphids, codling moth and fruit damage are monitored with the leaf/shoot/fruit counts and pheromone traps specified in the UC IPM apple protocol.', 'Authoritative protocol / standard', NULL, 'pheromone trap');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (78, 'Leaf discoloration and leaf fall', 'IPDM, senescence and end of productive life', 10, NULL, 'OAR90-93', 'Leaf discoloration and leaf fall are scored repeatedly on the same canopy population using BBCH senescence stages.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (79, 'Senescing-leaf photosynthesis, transpiration, stomatal conductance and F_v/F_m', 'IPDM, senescence and end of productive life', 10, NULL, 'OAR90-93', 'Gas exchange and F_v/F_m of senescing leaves are measured with the same IRGA and PAM protocols used for mature leaves.', 'Source paper protocol', NULL, 'IRGA');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (80, 'Senescing-leaf chlorophyll, mineral nutrients, protein, amino acids, soluble sugars and H_2O_2', 'IPDM, senescence and end of productive life', 10, NULL, 'OAR90-93', 'Senescing-leaf pigments, nutrients, protein, amino acids, sugars and H_2O_2 are measured from fixed leaf samples with the cited biochemical assays.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (81, 'Senescence phytohormones (CK, GA, ethylene, SA, ABA, JA)', 'IPDM, senescence and end of productive life', 10, NULL, 'OAR90-93', 'Senescence hormones are extracted from frozen leaf tissue and quantified by targeted LC-MS/MS with internal standards.', 'Source paper protocol', NULL, 'LC-MS/MS');
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (82, 'Stem soluble sugars, starch and total carbohydrates', 'IPDM, senescence and end of productive life', 10, NULL, 'OAR70-00', 'Stem soluble sugars are extracted with 80% ethanol and starch from the residue; both are quantified with the cited anthrone method.', 'Paper + authoritative protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (83, 'Whole-tree decline severity, survival and mortality', 'IPDM, senescence and end of productive life', 10, NULL, 'ODG03', 'Tree decline, survival and mortality are scored repeatedly on the same original tree positions with the cited decline scale.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (84, 'Multi-year yield/growth decline', 'IPDM, senescence and end of productive life', 10, NULL, 'ODG03', 'Multi-year growth and yield decline are calculated from repeated annual measurements on the same trees.', 'Source paper protocol', NULL, NULL);
INSERT INTO measurement_protocol (protocol_id, indicator, category, category_id, method_variant, stage_scope, protocol_text, protocol_basis, formula_latex, instruments) VALUES (85, 'Internal trunk necrosis and root-system deterioration', 'IPDM, senescence and end of productive life', 10, NULL, 'ODG03', 'Trunk necrosis is measured as necrotic area divided by total cross-sectional wood area; root deterioration is quantified from excavated and scanned roots.', 'Source paper protocol', NULL, 'scanned');
